// ExecutorServiceServer is the server API for ExecutorService service.
// All implementations must embed UnimplementedExecutorServiceServer
// for forward compatibility.
//
// ExecutorService：K8s 交互、故障检测、命令执行
type ExecutorServiceServer interface {
	// 启动集群 Watch（Pod/Node 事件监听）
	StartWatch(context.Context, *StartWatchRequest) (*StartWatchResponse, error)
	// 停止集群 Watch
	StopWatch(context.Context, *StopWatchRequest) (*StopWatchResponse, error)
	// 执行单条命令（白名单+dry-run+安全检查）
	ExecuteCommand(context.Context, *ExecuteCommandRequest) (*ExecuteCommandResponse, error)
	// 执行修复计划（流式返回每步进度）
	ExecutePlan(*ExecutePlanRequest, grpc.ServerStreamingServer[ExecutePlanResponse]) error
	// 回滚修复计划（逆序执行 rollback_command）
	RollbackPlan(context.Context, *RollbackPlanRequest) (*RollbackPlanResponse, error)
	// 集群健康检查（ServerVersion + 更新状态）
	HealthCheck(context.Context, *HealthCheckRequest) (*HealthCheckResponse, error)
	// 采集配额快照
	CollectQuota(context.Context, *CollectQuotaRequest) (*CollectQuotaResponse, error)
	// 执行脚本（自定义任务 script 类型）
	RunScript(context.Context, *RunScriptRequest) (*RunScriptResponse, error)
	// 批量执行（流式返回每集群结果）
	BatchExecute(*BatchExecuteRequest, grpc.ServerStreamingServer[BatchExecuteResponse]) error
	// 查询 Pod 状态（恢复判定：phase/ready/restartCount/容器状态）
	GetPodStatus(context.Context, *GetPodStatusRequest) (*GetPodStatusResponse, error)
	// 修复镜像拉取失败：定位 Deployment → 参考集群内其他服务的 imagePullSecrets → 补上
	RepairImagePull(context.Context, *RepairImagePullRequest) (*RepairImagePullResponse, error)
	// 查询 Deployment 副本状态（Pod 重建后判断是否恢复）
	GetDeploymentStatus(context.Context, *GetDeploymentStatusRequest) (*GetDeploymentStatusResponse, error)
	// 容器内只读命令执行（应用诊断：ps/env/cat/ss/df 等白名单命令）
	ExecInPod(context.Context, *ExecInPodRequest) (*ExecInPodResponse, error)
	// 列出 Deployment 所有 Pod 状态（验证修复是否真正恢复，区分新旧版本副本）
	ListDeploymentPods(context.Context, *ListDeploymentPodsRequest) (*ListDeploymentPodsResponse, error)
	// 列出集群全部 Pod 的重启信息（N5：重启原因 AI 诊断的检测数据源）
	ListPodRestartInfo(context.Context, *ListPodRestartInfoRequest) (*ListPodRestartInfoResponse, error)
	QueryPrometheus(context.Context, *QueryPrometheusRequest) (*QueryPrometheusResponse, error)
	// 高峰期资源采集（R1：工作负载 P80/P95 CPU/内存用量，Prometheus 聚合）
	GetPeakUsage(context.Context, *GetPeakUsageRequest) (*GetPeakUsageResponse, error)
	// 查看 Pod 容器日志（logs）
	GetPodLogs(context.Context, *GetPodLogsRequest) (*GetPodLogsResponse, error)
	// 获取 Pod YAML（只读）
	GetPodYaml(context.Context, *GetPodYamlRequest) (*GetPodYamlResponse, error)
	// 应用 Pod YAML（修改配置后应用）
	ApplyPodYaml(context.Context, *ApplyPodYamlRequest) (*ApplyPodYamlResponse, error)
	// 命名空间 Pod 列表（含创建时间/就绪/重启，集群管理容器组用）
	ListPods(context.Context, *ListPodsRequest) (*ListPodsResponse, error)
	// Pod 详情（含容器组内各容器：镜像/状态/就绪/重启；点击 Pod 展开用）
	GetPodDetail(context.Context, *GetPodDetailRequest) (*GetPodDetailResponse, error)
	// 工作负载（Deployment/StatefulSet/DaemonSet）Pod 模板的挂载配置（volumes + 容器 volumeMounts）
	GetWorkloadMounts(context.Context, *GetWorkloadMountsRequest) (*GetWorkloadMountsResponse, error)
	// 集群管理其它资源：服务/路由(Ingress)/ConfigMap/Secret/存储(PVC)
	ListMiscResources(context.Context, *ListMiscResourcesRequest) (*ListMiscResourcesResponse, error)
	// 单个 Pod 的事件（k8s Event）
	GetPodEvents(context.Context, *GetPodEventsRequest) (*GetPodEventsResponse, error)
	// 获取工作负载（整个服务）YAML：Deployment/StatefulSet/DaemonSet/CronJob
	GetWorkloadYaml(context.Context, *GetWorkloadYamlRequest) (*GetWorkloadYamlResponse, error)
	// 应用工作负载（整个服务）YAML
	ApplyWorkloadYaml(context.Context, *ApplyWorkloadYamlRequest) (*ApplyWorkloadYamlResponse, error)
	// 删除配置类对象（ConfigMap/Secret）
	DeleteResource(context.Context, *DeleteResourceRequest) (*DeleteResourceResponse, error)
	// 清理已驱逐（Evicted）的 Pod（终态对象，删除不影响业务）
	CleanupEvicted(context.Context, *CleanupEvictedRequest) (*CleanupEvictedResponse, error)
	// 命名空间列表（name + labels，R19 发布入口标签门控用）
	ListNamespaces(context.Context, *ListNamespacesRequest) (*ListNamespacesResponse, error)
	// ServiceAccount 列表（含角色反查 + 关联 secret）
	ListServiceAccounts(context.Context, *ListServiceAccountsRequest) (*ListServiceAccountsResponse, error)
	// 云原生 RBAC 接入：能力探测 + 下发三档 ClusterRole + 可选自举 automation SA
	SetupRBAC(context.Context, *SetupRBACRequest) (*SetupRBACResponse, error)
	// 项目/成员变更 → reconcile RoleBinding（绑组）
	ReconcileRoleBindings(context.Context, *ReconcileRoleBindingsRequest) (*ReconcileRoleBindingsResponse, error)
	// 工作负载运维（专项 D：集群管理云原生改造）
	ListWorkloads(context.Context, *ListWorkloadsRequest) (*ListWorkloadsResponse, error)
	ScaleWorkload(context.Context, *ScaleWorkloadRequest) (*ScaleWorkloadResponse, error)
	RolloutWorkload(context.Context, *RolloutWorkloadRequest) (*RolloutWorkloadResponse, error)
	RolloutHistory(context.Context, *RolloutHistoryRequest) (*RolloutHistoryResponse, error)
	// R57：HPA（水平自动扩缩容）管理
	ListHPA(context.Context, *ListHPARequest) (*ListHPAResponse, error)
	GetHPA(context.Context, *GetHPARequest) (*GetHPAResponse, error)
	ApplyHPA(context.Context, *ApplyHPARequest) (*ApplyHPAResponse, error)
	DeleteHPA(context.Context, *DeleteHPARequest) (*DeleteHPAResponse, error)
	// R60：发布历史与版本对比
	ListRevisions(context.Context, *ListRevisionsRequest) (*ListRevisionsResponse, error)
	GetRevisionTemplate(context.Context, *GetRevisionTemplateRequest) (*GetRevisionTemplateResponse, error)
	UpdateProbe(context.Context, *UpdateProbeRequest) (*UpdateProbeResponse, error)
	RecreateWorkload(context.Context, *RecreateWorkloadRequest) (*RecreateWorkloadResponse, error)
	// 工作负载回滚执行通道（R70 前置）：等价 kubectl rollout undo，仅 deployment
	RollbackWorkload(context.Context, *RollbackWorkloadRequest) (*RollbackWorkloadResponse, error)
	// 交互式终端（TTY）：双向流（stdin/stdout/resize）
	ExecPodStream(grpc.BidiStreamingServer[ExecPodStreamFrame, ExecPodStreamFrame]) error
	// JVM 深度诊断（jstack/jfr/heapdump/jcmd），R2
	JvmDiagnose(context.Context, *JvmDiagnoseRequest) (*JvmDiagnoseResponse, error)
	// 采集 JVM 启动参数（-Xms/-Xmx/-Xss/-XX:MaxMetaspaceSize + java_version），R2
	JvmParams(context.Context, *JvmParamsRequest) (*JvmParamsResponse, error)
	mustEmbedUnimplementedExecutorServiceServer()
}

